<?php use Pjas\Http\{Csrf,View};use Pjas\Support\Time; ?>
<h1>削除済み・管理を終了したサイト</h1><p class="sub">コード・共有データと設定を30日間保管します。管理対象から外しただけのサイトは、保存期限なく管理を再開できます。履歴とサイト名は削除後も保持します。</p>
<?php foreach($rows as $r):?><div class="card"><div class="card-h"><?= View::e($r['name']) ?> · <?= View::e(['deleting'=>'作業中','restoring'=>'復元中','deleted'=>'削除済み','detached'=>'管理対象外','failed'=>'状態の確認が必要','expired'=>'復元期限終了'][$r['state']]??$r['state']) ?></div><div class="card-b"><p><?= View::e($r['domain']) ?> · <?= $r['expires']?'復元期限：'.View::e(Time::display(gmdate('c',(int)$r['expires']))):'管理を再開できます' ?></p><p><?= View::e($r['detail']) ?></p><?php if($r['job_id']):?><a class="btn" href="/jobs/<?= $r['job_id'] ?>">作業履歴を見る</a><?php endif;?>
<?php if(in_array($r['state'],['deleted','detached','failed','deleting','restoring'],true)&&($r['state']!=='deleted'||!$r['expires']||$r['expires']>time())):?><details><summary>復元・管理再開する（失敗・中断した作業の復旧もこちら）</summary><p>同名のフォルダや設定がある場合は上書きせず中断します。自動公開は停止状態で復元します。</p><form method="post" action="/services/<?= View::e($r['name']) ?>/delete"><?= Csrf::field() ?><input type="hidden" name="action" value="restore"><div class="field"><label>サイト名を入力</label><input name="confirm_name" required autocomplete="off"></div><div class="field"><label>現在のパスワード</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn p">復元して管理を再開する</button></form></details><?php endif;?></div></div><?php endforeach;?><?php if(!$rows):?><p>削除済みのサイトはありません。</p><?php endif;?>
